//! RDKit parity test for the 3D (conformer-based) descriptors.
//!
//! Reads `tests/data/parity_3d.sdf` (ETKDGv3 conformers with explicit H of a
//! sample of `parity_molecules.smi`) with FerrumChem's SDF reader, which, like
//! RDKit's `MolFromMolBlock` defaults, sanitizes and removes the hydrogens, and
//! compares PMI1/PMI2/PMI3/Asphericity (`rdMolDescriptors.CalcPMI1..3`,
//! `CalcAsphericity`) and per-atom perception against
//! `tests/data/rdkit_3d_parity_reference.csv` (generated by
//! `scripts/generate_parity_reference.py`).
//!
//! Known deviations are tracked per column in `tests/data/rdkit_3d_parity_baseline.tsv`;
//! see `rdkit_parity.rs` for the baseline workflow (`FERRUM_UPDATE_PARITY_BASELINE`,
//! `FERRUM_PARITY_VERBOSE`).
//!
//! Known deviation:
//! - `perception`, 1 molecule (`N[Pt](N)(Cl)Cl`): RDKit's mol-block reader
//!   assigns a transient tetrahedral chiral tag to Pt from the 3D coordinates
//!   during sanitization, which makes `setHybridization` report SP3 (the same
//!   molecule from SMILES or a 2D block is UNSPECIFIED). FerrumChem does not
//!   perceive chirality from 3D coordinates; the 3D descriptors are unaffected.

mod common;

#[test]
fn rdkit_3d_parity() {
    common::parity::run_parity_sdf(
        "RDKit 3D",
        "parity_3d.sdf",
        "rdkit_3d_parity_reference.csv",
        "rdkit_3d_parity_baseline.tsv",
    );
}
